"""Small H.264/AAC HLS ladder, generated by a leased worker, never an API worker."""
import hashlib
import json
import math
import os
from pathlib import Path
import shutil
import subprocess
import tempfile
import uuid
from datetime import timedelta

from django.conf import settings
from django.core.files import File
from django.db import transaction
from django.db.models import Q
from django.utils import timezone

from social.models import MomentVideo, MomentVideoFile, MomentDraftPhoto
from social.services.moment_publication import draft_for
from social.services.moment_service import compensate_upload
from social.services.moment_video import MAX_BYTES


class InvalidVideo(Exception):
    pass


def binary(name):
    return getattr(settings, f"MOMENT_{name.upper()}_BIN", None) or shutil.which(name) or name


def run_media(args, *, timeout=180):
    # Commands are fixed argument arrays, not shell commands. Uploaded media may
    # not open network protocols; stderr can include filenames, so never log it.
    with tempfile.TemporaryFile() as output:
        subprocess.run(args, stdin=subprocess.DEVNULL, stdout=output,
            stderr=subprocess.DEVNULL, timeout=timeout, check=True)
        output.seek(0)
        data = output.read(65537)
        if len(data) > 65536:
            raise InvalidVideo()
        return data


def encode(source, directory):
    try:
        metadata = json.loads(run_media([binary("ffprobe"), "-v", "error", "-protocol_whitelist", "file,pipe",
            "-format_whitelist", "mov,matroska,webm",
            "-probesize", "5000000", "-analyzeduration", "5000000", "-show_entries",
            "format=duration,format_name:stream=codec_type,width,height,duration,color_transfer,avg_frame_rate",
            "-of", "json", str(source)], timeout=20))
        streams = metadata["streams"]
        visual = [s for s in streams if s.get("codec_type") == "video"]
        fmt = metadata["format"]
        duration = max(float(s.get("duration", 0)) for s in [fmt, *streams])
        if (len(visual) != 1 or len(streams) > 4 or not math.isfinite(duration)
                or not .1 <= duration <= 60.05
                or not set(fmt["format_name"].split(",")) & {"mov", "mp4", "matroska", "webm"}):
            raise InvalidVideo()
        width, height = int(visual[0]["width"]), int(visual[0]["height"])
        if not (2 <= width <= 4096 and 2 <= height <= 4096 and width * height <= 9_000_000):
            raise InvalidVideo()
    except (KeyError, ValueError, TypeError, subprocess.CalledProcessError, subprocess.TimeoutExpired):
        raise InvalidVideo()
    # Convert HDR to SDR for predictable brightness and hardware-compatible output.
    tone = ("zscale=t=linear:npl=100,format=gbrpf32le,zscale=p=bt709,"
            "tonemap=tonemap=hable:desat=0,zscale=t=bt709:m=bt709:r=tv,") if visual[0].get("color_transfer") in {"smpte2084", "arib-std-b67"} else ""
    base = [binary("ffmpeg"), "-nostdin", "-v", "error", "-y", "-protocol_whitelist", "file,pipe",
        "-format_whitelist", "mov,matroska,webm",
        "-threads", "2", "-filter_threads", "1", "-i", str(source)]
    renditions = [("360", 640, 650)]
    if max(width, height) > 640:
        renditions.append(("720", 1280, 2200))
    for label, edge, rate in renditions:
        scale = f"scale=w='min({edge},iw)':h='min({edge},ih)':force_original_aspect_ratio=decrease:force_divisible_by=2"
        run_media([*base, "-map", "0:v:0", "-map", "0:a:0?", "-sn", "-dn", "-map_metadata", "-1",
            "-vf", tone + scale + ",setsar=1,fps=30,format=yuv420p", "-c:v", "libx264", "-preset", "veryfast",
            "-threads", "2", "-profile:v", "main", "-crf", "23", "-maxrate", f"{rate}k", "-bufsize", f"{rate*2}k",
            "-g", "60", "-keyint_min", "60", "-sc_threshold", "0", "-c:a", "aac", "-b:a", "96k", "-ac", "2",
            "-ar", "48000", "-t", "60", "-max_muxing_queue_size", "1024", "-f", "hls", "-hls_time", "2",
            "-hls_playlist_type", "vod", "-hls_flags", "independent_segments", "-hls_segment_filename",
            str(directory / f"{label}_%03d.ts"), str(directory / f"{label}.m3u8")])
    run_media([*base, "-map", "0:v:0", "-vf", tone + "scale=w='min(640,iw)':h='min(640,ih)':force_original_aspect_ratio=decrease",
        "-frames:v", "1", "-update", "1", "-q:v", "3", "-map_metadata", "-1", str(directory / "poster.jpg")], timeout=30)
    # No remote references or credential-bearing URLs in the manifests.
    manifest = "#EXTM3U\n#EXT-X-VERSION:3\n#EXT-X-INDEPENDENT-SEGMENTS\n"
    for label, _, rate in renditions:
        manifest += f"#EXT-X-STREAM-INF:BANDWIDTH={int((rate+150)*1250)}\n{label}.m3u8\n"
    (directory / "master.m3u8").write_text(manifest)
    from PIL import Image
    with Image.open(directory / "poster.jpg") as poster:
        dimensions = poster.size
    files = sorted(directory.iterdir())
    if len(files) > 70 or sum(f.stat().st_size for f in files) > 100 * 1024 * 1024:
        raise InvalidVideo()
    return round(duration * 1000), dimensions, files


def process_one():
    cutoff = timezone.now() - timedelta(minutes=10)
    with transaction.atomic():
        candidate = MomentVideo.objects.filter(Q(state="queued") | Q(state="processing", updated_at__lt=cutoff)).order_by("updated_at").first()
        if candidate is None:
            return False
        video = MomentVideo.objects.select_for_update().filter(pk=candidate.pk).first()
        if video is None:
            return True
        if video.state not in {"queued", "processing"} or (video.state == "processing" and video.updated_at >= cutoff):
            return True
        if video.attempts >= 3:
            video.state, video.error_code = "failed", "processing"
            video.save(update_fields=["state", "error_code"])
            return True
        lease = uuid.uuid4()
        video.state, video.lease, video.updated_at = "processing", lease, timezone.now()
        video.attempts += 1
        video.save(update_fields=["state", "lease", "updated_at", "attempts"])
    saved, retained = [], False
    try:
        photo = MomentDraftPhoto.objects.select_related("draft", "draft__owner").get(video=video)
        draft_for(photo.draft.owner, photo.draft_id, editable=True)
        with tempfile.TemporaryDirectory(prefix="srisu-video-") as temp:
            root = Path(temp); source = root / "source"; output = root / "output"; output.mkdir()
            with source.open("wb") as target:
                for part in video.files.filter(name__startswith="upload_").order_by("name"):
                    with part.file.open("rb") as stream:
                        digest = hashlib.sha256()
                        for block in iter(lambda: stream.read(65536), b""):
                            digest.update(block); target.write(block)
                            if target.tell() > MAX_BYTES:
                                raise InvalidVideo()
                        if digest.hexdigest() != part.digest:
                            raise InvalidVideo()
                if target.tell() != video.source_bytes:
                    raise InvalidVideo()
            duration, dimensions, files = encode(source, output)
            storage = MomentVideoFile._meta.get_field("file").storage
            rows = []
            for path in files:
                name = f"couples/moments/videos/{video.pk.hex}/{lease.hex}/{path.name}"
                saved.append(name)
                with path.open("rb") as stream:
                    actual = storage.save(name, File(stream)); saved.append(actual)
                with path.open("rb") as stream:
                    digest = hashlib.file_digest(stream, "sha256").hexdigest()
                rows.append(MomentVideoFile(video=video, name=path.name, file=actual,
                    size=path.stat().st_size, digest=digest))
            with transaction.atomic():
                # Same draft->video lock order as upload/delete; recheck revoked membership.
                draft = draft_for(photo.draft.owner, photo.draft_id, lock=True, editable=True)
                current = MomentVideo.objects.select_for_update().get(pk=video.pk)
                if current.lease != lease or current.state != "processing" or not draft.photos.filter(pk=photo.pk).exists():
                    return True
                MomentVideoFile.objects.bulk_create(rows)
                poster = next(r for r in rows if r.name == "poster.jpg")
                draft.photos.filter(pk=photo.pk).update(image=poster.file.name, width=dimensions[0], height=dimensions[1], digest=poster.digest)
                current.state, current.error_code = "ready", ""
                current.duration_ms, current.width, current.height = duration, dimensions[0], dimensions[1]
                current.updated_at = timezone.now()
                current.save()
                # Original chunks cease to be retained once encoded and verified.
                current.files.filter(name__startswith="upload_").delete()
            retained = True
    except Exception as exc:
        code = "invalid_video" if isinstance(exc, InvalidVideo) else "processing"
        MomentVideo.objects.filter(pk=video.pk, lease=lease, state="processing").update(state="failed", error_code=code, updated_at=timezone.now())
    finally:
        if not retained:
            for name in set(saved):
                if not MomentVideoFile.objects.filter(file=name).exists():
                    compensate_upload(name)
    return True
